import attr
from typing import Optional


import logging
logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


@attr.s(cmp=False)
class RoutingInformation(object):
    """
    :param gateway: ip address of the gateway
    :param ip_prefix_length: the number of bits set in the subnet mask
    :param destIpAddr: destination ip address for this route in ip/mask format
    """
    gateway = attr.ib(type=str)
    ip_prefix_length = attr.ib(default=None, type=Optional[int])  # deprecated
    destIpAddr = attr.ib(default=None, type=Optional[str])

    def __attrs_post_init__(self):
        if self.ip_prefix_length is not None:
            self._warn_ip_prefix_length_deprecated()

    @staticmethod
    def _warn_ip_prefix_length_deprecated():
        logger.warning("'ip_prefix_length' in RoutingInformation is deprecated - use "
                       "ip/mask format when declaring ip address.")


# TODO: move it outside gnb module when major release
@attr.s(cmp=False)
class NetworkAddress(object):
    """
    :param v4: ipv4 ip address or ipv4/mask
    :param v6: ipv6 ip address or ipv6/mask
    :param vlan_id: VLAN identifier
    :param routing: network route that indicates that when trying to get to
    the specified destination, send the packets through the specified gateway
    """
    v4 = attr.ib(default=None, type=Optional[str])
    v6 = attr.ib(default=None, type=Optional[str])
    vlan_id = attr.ib(default=None, type=Optional[str])
    routing_v6 = attr.ib(default=None, type=Optional[RoutingInformation])
    routing_v4 = attr.ib(default=None, type=Optional[RoutingInformation])

    # routing parameter is deprecated since v8.50.0, use routing_v4 instead
    # XXX: leading underscores are removed by attribs in generated classes'
    # __init__() signature.
    _routing = attr.ib(default=None, type=Optional[RoutingInformation])

    def __attrs_post_init__(self):
        if self._routing is not None:
            self._warn_routing_deprecated()
            self.routing_v4 = self._routing

    @property
    def routing(self):
        self._warn_routing_deprecated()
        return self.routing_v4

    @routing.setter
    def routing(self, value):
        self._warn_routing_deprecated()
        self._routing = value
        self.routing_v4 = value

    @staticmethod
    def _warn_routing_deprecated():
        logger.warning("'routing' in NetworkAddress is deprecated - use "
                       "'routing_v4' instead.")
